        骨二科病房: ['骨二', '骨二科', '骨二科病房', '骨二病房', '骨二可', '骨科病房', '骨科住院', '骨科病区'],
        外一科病房: ['外一', '外一科', '外一科病房', '外一病房', '外科病房', '外科住院', '外科病区'],
